#include "stdafx.h"#include "..\MnemoWnd.h"#include "Queue.h"#include "..\Lang.h"//// Обработка кнопок//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~// Структураtypedef struct : public SPROLOZ  {  char szName[64];  COLORREF colorBkg[2];  char szParm[64];  int  nSet;  int nControl;//номер контрольной HS  int nTestLamp;//номер HS проверки ламп  bool bKlapan;//для клапана если nSet 1 то открыть, если 0 то закрыть   bool bPump;//для клапана если nSet 1 то открыть, если 0 то закрыть   bool bTestLamp;  bool bInvert;  } Queue_KcaOval;//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~void SendDataPump(Queue_KcaOval* p, SQueue& q){		CShPump* sh = (CShPump*)PipeSh;		if ( IsTypeOk )		{			  SSendToModel send;			  if (p->nSet==1)				lstrcpy( send.szValue, "Открыть" );// Имя переменной			  else			    lstrcpy( send.szValue, "Остановить" );// Имя переменной 			  int Old = 0;			  int New=1;			  send.Set( enumValueInt, &Old, &New );			  q.m_pPipe->SendData( p->nNumber, send );		 }}void SendDataKlapan(Queue_KcaOval* p, SQueue& q){	    CShKlapan* sh = (CShKlapan*)PipeSh;		if ( IsTypeOk )		{			  SSendToModel send;			  if (p->nSet==1)				lstrcpy( send.szValue, "Открыть" );// Имя переменной			  else			    lstrcpy( send.szValue, "Закрыть" );// Имя переменной 			  int Old = 0;			  int New=1;			  send.Set( enumValueInt, &Old, &New );			  q.m_pPipe->SendData( p->nNumber, send );		 }}void SendDataHS(Queue_KcaOval* p, SQueue& q,int nSet){		CShHS* sh = (CShHS*)PipeSh;		if ( IsTypeOk )		{		  SSendToModel send;		  lstrcpy( send.szValue, p->szParm );// Имя переменной		  bool Old = sh->mOn;//##?? //		  if (lstrcmp(p->szParm,"PV")==0)//			  Old = sh->PV;		  bool New = nSet;		  send.Set( enumValueBol, &Old, &New );		  q.m_pPipe->SendData( p->nNumber, send );		}}int PressKcaOval(DefinePress)  {  Queue_KcaOval* p = (Queue_KcaOval*)s;  if ( nCode == 0 )  {	  	if(p->bTestLamp)			SendDataHS(p,q,1);		return 0;  }  else  if ( nCode == 1 )  {		return 0;  }  else  if ( nCode == 3 )    return 0;  if(p->bTestLamp)  {		SendDataHS(p,q,0);		return 0;  }    if ( p->nSet!=-3)    {		 bool bSend=true;		if(IS_USED_REMOTE_CONTROL&&(p->nControl>=0))		{			CShHS* sh=(CShHS*)q.m_pPipe->Sh(p->nControl);			if ( IsTypeOk )				bSend=(sh->mOn); //##??		}		if (bSend)		{			if (!p->bKlapan)			{				if(!p->bPump)					SendDataHS(p,q,p->nSet);				else					SendDataPump(p,q);			}			else				SendDataKlapan(p,q);		}    }  return 0;  }//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~// Функция отображенияint PaintKcaOval(DefinePaint)  {	QueueP(Queue_KcaOval);	//	COLORREF color = p->colorBkg[0];	RECT rect = p->mRect;	bool bBadValue=false;    if (!p->bKlapan)	{		if(!p->bPump)		{			CShHS* sh = (CShHS*)PipeSh;			if ( IsTypeOk )			{				if (!sh->mOn) //##??				{					if (!p->bInvert)						color=p->colorBkg[0];					else						color=p->colorBkg[1];				}				else				{					if (!p->bInvert)						color=p->colorBkg[1];					else						color=p->colorBkg[0];				}//##??				if ((sh->PV==2)&&(q.m_dwMainTimer%2==0))//##??					return 0;			}			else				bBadValue=true;		}		else		{			CShPump* sh = (CShPump*)PipeSh;			if ( IsTypeOk )			{				if (sh->Eq_State( CPumpData::Work ))				{					if (!p->bInvert)						color=p->colorBkg[1];					else						color=p->colorBkg[0];				}				else				{					if (!p->bInvert)						color=p->colorBkg[0];					else						color=p->colorBkg[1];				}			}			else				bBadValue=true;		}	}	else	{		CShKlapan* sh = (CShKlapan*)PipeSh;		if ( IsTypeOk )		{			double dKlapan=sh->Vent;			bool bNol=true;			if (p->nSet==1)			{				if (dKlapan>=100)					bNol=false;			}			else			{				if (dKlapan<=0)					bNol=false;			}			if (bNol)				color=p->colorBkg[0];			else				color=p->colorBkg[1];		}	}	if (p->nTestLamp>=0)	{		CShHS* sh = (CShHS*)q.m_pPipe->Sh(p->nTestLamp);		if ( IsTypeOk )		{			if (sh->mOn)//##??				color=p->colorBkg[1];		}	}	CMyRgn rgn( hDC, color );	rgn.Ellipse( rect );	if ((bBadValue)&&( ::GetMnemoStyle() & MNEMO_EDIT ))	{		  color = 0x80ff;		  CMyRgn rgn( hDC, color );		  rgn.Ellipse( rect );	}	return 0;  }//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~void AddKcaOval(DefineTegs)  {  //  AddQueueEx(Queue_KcaOval);  // Код, посылаемый в АРМ  p->btSendType = QUEUE_BUTTON;  // Определение функции вывода  p->paint = &PaintKcaOval;  p->press = &PressKcaOval;  //  p->colorBkg[0]=0;  lstrcpy( p->szParm, "SP" );  p->nSet=-3;  p->nControl=-1;  p->nTestLamp=-1;  char szControl[64]="";  char szKlapan[64]="";  char szPump[64]="";  char szTestLamp[64]="";  char szParmControl[64]="";  p->bKlapan=false;  p->bPump=false;  p->bTestLamp=false;  p->bInvert=false;  //  STegObj obj[] =    {    { 'R', "rect"   , &p->mRect  },    { 'E', "rc"     , &p->mRect  },	{ 'A', "cBkg0" , &p->colorBkg[0] },	{ 'A', "cBkg1" , &p->colorBkg[1] },	{ 'S', "param"  , p->szParm, 63 },	{ 'I', "setHS"  , &p->nSet },	{ 'B', "bTestLamp"  , &p->bTestLamp },	{ 'B', "invert"  , &p->bInvert },	{ 'S', "control"  , szControl, 63 },	{ 'S', "klapanName"  , szKlapan, 63 },	{ 'S', "pumpName"  , szPump, 63 },	{ 'S', "testLampName"  , szTestLamp, 63 },	{ 'S', "ParmControl"  , szParmControl, 63 },    EXT_QUEUE  // Дополнительная информация    //    };  ::ParserObjScn( teg, obj, sizeof(obj)/sizeof(STegObj) );  p->nNumber  = def.GetActiveObj();   if ( *szKlapan )   {		p->nNumber = def.AddKind(id_Klapan,szKlapan);		p->bKlapan=true;   }   if ( *szPump )   {		p->nNumber = def.AddKind(id_Pump,szPump);		p->bPump=true;   }  //    if ( *szControl )		p->nControl = def.AddKind(id_HS,szControl);	if ( *szTestLamp )		p->nTestLamp = def.AddKind(id_HS,szTestLamp);	if ( *szParmControl)		lstrcpy(p->szParm,szParmControl);  }//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~